package claudecode

import (
	"strings"
	"testing"

	"github.com/lictor-ai/stele/internal/adapter"
)

func TestOwnedRules(t *testing.T) {
	file := RenderRules(twoRules)
	for name, data := range map[string]string{
		"rendered":  string(file),
		"BOM":       "\xef\xbb\xbf" + string(file),
		"CRLF":      strings.ReplaceAll(string(file), "\n", "\r\n"),
		"no rules":  string(RenderRules(nil)),
		"new intro": "<!-- Generated by stele from stele.md, v2. -->\nOther words.\n",
	} {
		if !OwnedRules([]byte(data)) {
			t.Errorf("%s: not owned", name)
		}
	}
	for name, data := range map[string]string{
		"the user's rules": "# Our rules\nAlways write tests.\n",
		"empty":            "",
		"header later":     "notes\n<!-- Generated by stele from stele.md. -->\n",
	} {
		if OwnedRules([]byte(data)) {
			t.Errorf("%s: owned", name)
		}
	}
}

// Freshness is about the rules the agent reads, not the template's words: a
// stele with another intro text must not rewrite a committed file.
func TestSameRules(t *testing.T) {
	want := RenderRules(twoRules)
	same := map[string]string{
		"identical":    string(want),
		"CRLF":         strings.ReplaceAll(string(want), "\n", "\r\n"),
		"header text":  strings.Replace(string(want), "Follow them in every change.", "Follow them.", 1),
		"first line":   strings.Replace(string(want), "Do not edit: run stele compile.", "Generated, do not edit.", 1),
		"blank blocks": strings.ReplaceAll(string(want), "\n<!-- stele rule", "\n\n\n<!-- stele rule"),
	}
	for name, disk := range same {
		if !SameRules([]byte(disk), want) {
			t.Errorf("%s: stale", name)
		}
	}
	stale := map[string]string{
		"a block edited": strings.Replace(string(want), "never exit", "exit at will", 1),
		"order changed":  string(RenderRules([]adapter.Rule{twoRules[1], twoRules[0]})),
		"a rule missing": string(RenderRules(twoRules[:1])),
		"no header":      strings.SplitN(string(want), "\n", 2)[1],
		"a duplicate":    string(want) + "\n<!-- stele rule r2 -->\nNever put credentials in code.\nRead them from the environment.\n",
	}
	for name, disk := range stale {
		if SameRules([]byte(disk), want) {
			t.Errorf("%s: not stale", name)
		}
	}
}

// Claude Code may hide HTML comments when it loads the file: an unclosed one
// in a rule could hide the rest of it from the agent while its hash counts it
// as read.
func TestRuleHashCommentMarkers(t *testing.T) {
	for _, r := range []adapter.Rule{
		{ID: "a", Body: "Before <!-- hidden after"},
		{ID: "b", Body: "Ends a comment --> here"},
		{ID: "c", Scope: []string{"src/<!--/**"}, Body: "x"},
		{ID: "d", Scope: []string{"-->"}, Body: "x"},
	} {
		if h := RuleHash(r); h != "" {
			t.Errorf("RuleHash(%+v) = %q, want none", r, h)
		}
	}
	if RuleHash(adapter.Rule{ID: "e", Body: "A plain rule <with> angle brackets."}) == "" {
		t.Error("a plain rule got no hash")
	}
}

func TestMaxRulesChars(t *testing.T) {
	if MaxRulesChars != 40000 {
		t.Errorf("MaxRulesChars = %d", MaxRulesChars)
	}
}
